"""Consolidate redundant marker spellings by accepted identity route, preserving membership."""
import json,hashlib
from datetime import datetime,timezone
import numpy as np,pandas as pd
r=PROJECT_ROOT/'runs/20261106_v7_publication_marker_annotation_v1';c=r/'stage_c3_exact_identity_freeze';o=r/'stage_c4_harmonized_identity_freeze';o.mkdir(exist_ok=False)
assert json.loads((c/'independent_freeze_audit.json').read_text())['status']=='PASS'
mapping={0:('Tcell','CD3D;TRAC'),1:('NK','KLRD1;GNLY'),2:('Bcell','MS4A1;CD79A'),3:('Plasma','MZB1;JCHAIN'),4:('Myeloid','LST1;CSF1R'),5:('Dendritic','LILRA4;TCF4'),6:('Dendritic','CLEC9A;BATF3'),7:('Dendritic','CD1C;FCER1A'),8:('Mast','TPSAB1;CPA3'),10:('Granulocyte','FCGR3B;CSF3R'),12:('Endothelial','VWF;PECAM1'),13:('Mural','RGS5;PDGFRB'),14:('Fibroblast','COL1A1;DCN'),15:('Epithelial','EPCAM;KRT18'),16:('Melanocytic','PMEL;MLANA'),17:('Neural','TUBB3;MAP2'),18:('Glial','GFAP;OLIG1'),19:('HSPC','SPINK2;CD34'),20:('Erythroid','GYPA;AHSP'),21:('Platelet_Megakaryocytic','PPBP;TUBB1')}
t=pd.read_pickle(c/'annotation_all_cells_with_release_status_PRIVATE.pkl.gz');take=t.annotation_frozen.to_numpy();old=t.loc[take,['final_annotation','representative_markers','accepted_rule_id']].copy();t['final_annotation']=t.final_annotation.astype(object);t['representative_markers']=t.representative_markers.astype(object)
for j,(parent,markers) in mapping.items():
 mask=t.annotation_frozen & t.accepted_rule_id.eq(j).fillna(False);assert t.loc[mask,'final_parent'].astype(str).eq(parent).all();t.loc[mask,'final_annotation']=parent+'_'+markers.replace(';','_');t.loc[mask,'representative_markers']=markers
assert set(t.loc[take,'accepted_rule_id'].astype(int))==set(mapping)
t['release_version']='V7_marker_identity_20261106_v3'
for col in t.select_dtypes(include=object):t[col]=t[col].astype('category')
pd.DataFrame([{'accepted_rule_id':j,'final_parent':p,'final_annotation':p+'_'+g.replace(';','_'),'representative_markers':g} for j,(p,g) in mapping.items()]).to_csv(o/'harmonized_name_registry.tsv',sep='\t',index=False)
old['new_final_annotation']=t.loc[take,'final_annotation'].astype(str).to_numpy();old.groupby(['accepted_rule_id','final_annotation','new_final_annotation'],observed=True).size().rename('n_cells').reset_index().to_csv(o/'name_consolidation_audit.tsv',sep='\t',index=False)
t.to_pickle(o/'annotation_all_cells_with_release_status_PRIVATE.pkl.gz',compression={'method':'gzip','compresslevel':1});f=t.loc[take].copy();f.to_pickle(o/'marker_identity_frozen_cells_PRIVATE.pkl.gz',compression={'method':'gzip','compresslevel':1});f.to_csv(o/'marker_identity_frozen_cells_PRIVATE.tsv.gz',sep='\t',compression={'method':'gzip','compresslevel':1},na_rep='NA')
f.groupby(['final_parent','final_annotation','representative_markers','freeze_basis'],observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'frozen_identity_counts.tsv',sep='\t',index=False)
t.groupby(['freeze_status','QC_action'],observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'all_cell_release_status_counts.tsv',sep='\t',index=False)
t.groupby(['frozen_parent','frozen_label','final_parent','final_annotation','freeze_status'],observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'historical_to_new_identity_counts.tsv',sep='\t',index=False,na_rep='')
f.groupby(['audit_group','accepted_rule_id','final_parent','final_annotation'],observed=True,dropna=False).size().rename('n_frozen_cells').reset_index().to_csv(o/'frozen_group_counts.tsv',sep='\t',index=False)
out={'status':'harmonized_names_written_pending_independent_audit','UTC':datetime.now(timezone.utc).isoformat(),'annotation_version':'V7_marker_identity_20261106_v3','n_frozen':len(f),'n_labels':f.final_annotation.nunique(),'n_parents':f.final_parent.nunique(),'membership_or_parent_decisions_changed':False,'reason':'Consolidate synonymous group-based marker names by previously accepted identity route; name markers are subsequently verified on actual retained cells. The two-cell GP1BB name failed the previous terminal check; that failed release was never accepted.','all_atlas_publication_acceptance':False,'files':[{'name':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in o.iterdir() if p.is_file()]};(o/'complete.json').write_text(json.dumps(out,indent=2));print(json.dumps({k:v for k,v in out.items() if k!='files'}))
